    whistle:      { vol: 0.65, gap: 0.10, layers: [{ src: 'whistle' }] },
    aimStart:     { vol: 0.55, gap: 0.10, layers: [{ src: 'aimStart' }] },
    aimFull:      { vol: 0.60, gap: 0.10, layers: [{ src: 'aimFull' }] },
    hookLaunch:   { vol: 1.00, gap: 0.08, layers: [{ src: 'hookLaunchA' }, { src: 'hookLaunchB', gain: 0.7 }] },
    hookCancel:   { vol: 0.50, gap: 0.08, layers: [{ src: 'hookCancel' }] },
    plateOn:      { vol: 0.60, gap: 0.06, layers: [{ src: 'plate' }] },
    plateOff:     { vol: 0.50, gap: 0.06, layers: [{ src: 'plate', rate: 0.75 }] },
    gateOpen:     { vol: 0.60, gap: 0.10, layers: [{ src: 'gateOpen', delay: 0.04 }] },
    gateClose:    { vol: 0.65, gap: 0.10, layers: [{ src: 'gateClose', delay: 0.04 }] },
    liftMove:     { vol: 0.40, gap: 0.15, layers: [{ src: 'liftMove' }] },
    seesaw:       { vol: 0.70, gap: 0.08, layers: [{ src: 'seesaw' }] },
    seesawLaunch: { vol: 0.80, gap: 0.08, layers: [{ src: 'seesawLaunch', delay: 0.03 }] },
    keyGet:       { vol: 0.75, gap: 0.10, layers: [{ src: 'keyGet' }] },
    lockOpen:     { vol: 0.80, gap: 0.15, layers: [{ src: 'lockOpenA' }, { src: 'keyGet', delay: 0.10, rate: 1.26, gain: 0.7 }] },
